-- IngrainedCut schema. Idempotent: safe to run on every deploy (scripts/migrate.mjs).
-- Auth tables generated by: npx auth@latest generate --config lib/auth.ts

create table if not exists "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table if not exists "session" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);

create table if not exists "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table if not exists "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create index if not exists "session_userId_idx" on "session" ("userId");

create index if not exists "account_userId_idx" on "account" ("userId");

create index if not exists "verification_identifier_idx" on "verification" ("identifier");

-- Projects: the timeline only. Media files stay on each user's computer.
create table if not exists "project" ("id" text not null primary key, "user_id" text not null references "user" ("id") on delete cascade, "name" text not null, "data" text not null, "duration" double precision default 0 not null, "clip_count" integer default 0 not null, "created_at" timestamptz default CURRENT_TIMESTAMP not null, "updated_at" timestamptz default CURRENT_TIMESTAMP not null);

create index if not exists "project_user_idx" on "project" ("user_id", "updated_at");

-- Ad-free supporters (lib/supporter.ts). Each account gets a code to put in its Ko-fi message.
create table if not exists "supporter_code" ("user_id" text not null primary key references "user" ("id") on delete cascade, "code" text not null unique, "created_at" timestamptz default CURRENT_TIMESTAMP not null);

-- Ko-fi payments reported by its webhook; user_id is the account they were matched to (by code, else by email).
create table if not exists "kofi_payment" ("transaction_id" text not null primary key, "email" text not null, "amount" numeric not null, "currency" text not null, "type" text not null, "user_id" text references "user" ("id") on delete set null, "paid_at" timestamptz not null, "received_at" timestamptz default CURRENT_TIMESTAMP not null);

create index if not exists "kofi_payment_user_idx" on "kofi_payment" ("user_id");

create index if not exists "kofi_payment_email_idx" on "kofi_payment" ("email");

-- "Open through the helper" (lib/helperLink.ts): when the browser won't let the website reach the helper, the site hands
-- the signed-in account to the helper with a one-time code, and the helper then calls the API with its own token.
create table if not exists "helper_code" ("code_hash" text not null primary key, "user_id" text not null references "user" ("id") on delete cascade, "expires_at" timestamptz not null);

create table if not exists "helper_token" ("token_hash" text not null primary key, "user_id" text not null references "user" ("id") on delete cascade, "created_at" timestamptz default CURRENT_TIMESTAMP not null, "last_used_at" timestamptz default CURRENT_TIMESTAMP not null);

create index if not exists "helper_token_user_idx" on "helper_token" ("user_id");
